CREATE OR REPLACE FUNCTION public.check_po_receival_allocations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare issuance_id uuid; line_id uuid; snapshot jsonb; header jsonb; expected jsonb; actual jsonb;
begin
 if tg_op='UPDATE' and row(new.source_purchase_order_issuance_id,new.source_purchase_order_line_id,new.source_allocation_key) is distinct from row(old.source_purchase_order_issuance_id,old.source_purchase_order_line_id,old.source_allocation_key) then raise exception 'PO receival source identity is immutable.'; end if;
 issuance_id:=coalesce(new.source_purchase_order_issuance_id,old.source_purchase_order_issuance_id);
 line_id:=coalesce(new.source_purchase_order_line_id,old.source_purchase_order_line_id);
 select order_snapshot,value into header,snapshot from public.purchase_order_issuances i cross join lateral jsonb_array_elements(i.lines_snapshot) where i.id=issuance_id and value->>'purchase_order_line_id'=line_id::text;
 if header->>'reservation_allocation_version' is distinct from '1' then return null; end if;
 if exists(select 1 from public.pending_receivals where source_purchase_order_issuance_id=issuance_id and source_purchase_order_line_id=line_id and (quantity_expected<=0 or quantity_received<0 or quantity_received>quantity_expected or material_name is distinct from snapshot->>'material' or unit is distinct from snapshot->>'unit' or temporary_job_label is not null or coalesce(is_earmarked,false) is distinct from (production_job_id is not null))) then raise exception 'Issued PO receipt identity or quantity cannot be changed; cancel an undelivered balance instead.'; end if;
 select coalesce(jsonb_object_agg(a->>'production_job_id',(a->>'quantity')::numeric),'{}'::jsonb) into expected from jsonb_array_elements(snapshot->'reservation_allocations') a;
 expected:=expected||jsonb_build_object('stock',(snapshot->>'quantity')::numeric-(select coalesce(sum((a->>'quantity')::numeric),0) from jsonb_array_elements(snapshot->'reservation_allocations') a));
 select coalesce(jsonb_object_agg(job,qty),'{}'::jsonb) into actual from (select coalesce(production_job_id::text,'stock') job,sum(quantity_expected) qty from public.pending_receivals where source_purchase_order_issuance_id=issuance_id and source_purchase_order_line_id=line_id group by production_job_id) totals;
 if not(actual?'stock') then actual:=actual||'{"stock":0}'::jsonb; end if;
 if actual<>expected then raise exception 'PO receipt portions must reconcile to the immutable Job allocations and general-stock remainder.'; end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_receiving_document_import(p_document_id uuid, p_actor text)
 RETURNS TABLE(pending_receival_id uuid, receiving_document_line_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform public.require_app_capability('adjustInventory');
  if exists(select 1 from public.receiving_documents where id=p_document_id and status='confirmed') then
    return query select l.pending_receival_id,l.id from public.receiving_document_lines l where l.receiving_document_id=p_document_id and l.included order by l.source_order;
    return;
  end if;
  if exists(select 1 from public.receiving_document_lines where receiving_document_id=p_document_id and included and resolution_type='unresolved') then
    raise exception 'Every included Receiving line must be reviewed before confirmation.';
  end if;
  return query select * from public.tenops_confirm_receiving_document_import_impl(p_document_id,p_actor);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_allocated_po_receivals(p_issuance_id uuid, p_lines jsonb, p_actor text)
 RETURNS TABLE(pending_receival_id uuid, source_line_id uuid, source_line_number integer, creation_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare issuance public.purchase_order_issuances%rowtype; submitted jsonb; item jsonb; allocation jsonb; base public.pending_receivals%rowtype; generated record; target_job public.jobs%rowtype; remainder numeric; allocated numeric; is_first boolean;
begin
 if coalesce(auth.role(), '') <> 'service_role' then
  perform public.require_app_capability('adjustInventory');
 end if;
 select * into strict issuance from public.purchase_order_issuances where id=p_issuance_id for update;
 if issuance.order_snapshot->>'reservation_allocation_version' is distinct from '1' then
  return query select * from public.po_base_create_pending_receivals(p_issuance_id,p_lines,p_actor); return;
 end if;
 if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines)=0 then raise exception 'Select PO lines.'; end if;
 for submitted in select value from jsonb_array_elements(p_lines) loop
  select value into strict item from jsonb_array_elements(issuance.lines_snapshot) where value->>'purchase_order_line_id'=submitted->>'source_line_id';
  if exists(select 1 from public.pending_receivals r where r.source_purchase_order_issuance_id=p_issuance_id and r.source_purchase_order_line_id=(item->>'purchase_order_line_id')::uuid) then
   return query select r.id,r.source_purchase_order_line_id,r.source_purchase_order_line_number,'existing'::text from public.pending_receivals r where r.source_purchase_order_issuance_id=p_issuance_id and r.source_purchase_order_line_id=(item->>'purchase_order_line_id')::uuid; continue;
  end if;
  if (submitted->>'quantity_expected')::numeric is distinct from (item->>'quantity')::numeric or submitted->>'unit' is distinct from item->>'unit' or submitted->>'material_name' is distinct from item->>'material' then raise exception 'Allocated receipts retain issued material, quantity and order unit. Record short deliveries through partial receiving.'; end if;
  select * into generated from public.po_base_create_pending_receivals(p_issuance_id,jsonb_build_array(submitted),p_actor);
  select * into strict base from public.pending_receivals where id=generated.pending_receival_id;
  select coalesce(sum((a->>'quantity')::numeric),0) into allocated from jsonb_array_elements(item->'reservation_allocations') a;
  remainder:=(item->>'quantity')::numeric-allocated; is_first:=true;
  for allocation in select value from jsonb_array_elements((item->'reservation_allocations')||case when remainder>0 then jsonb_build_array(jsonb_build_object('quantity',remainder,'production_job_id',null)) else '[]'::jsonb end) loop
   target_job:=null;
   if nullif(allocation->>'production_job_id','') is not null then select * into strict target_job from public.jobs where id=(allocation->>'production_job_id')::uuid; end if;
   if is_first then
    update public.pending_receivals set quantity_expected=(allocation->>'quantity')::numeric,production_job_id=target_job.id,temporary_job_label=null,is_earmarked=target_job.id is not null,earmarked_job_name=case when target_job.id is not null then concat_ws(' — ',nullif(target_job.job_number,''),target_job.name) end,earmark_notes=case when target_job.id is not null then 'Reserved by immutable PO line allocation.' end where id=base.id;
    pending_receival_id:=base.id; is_first:=false;
   else
    insert into public.pending_receivals(vendor,material_name,size,category,quantity_expected,quantity_received,unit,location,pallet_number,status,ordered_by,order_date,eta,notes,is_earmarked,earmarked_job_name,earmark_notes,production_job_id,source_purchase_order_issuance_id,source_purchase_order_line_id,source_purchase_order_line_number,source_purchase_order_number,source_allocation_key)
    values(base.vendor,base.material_name,base.size,base.category,(allocation->>'quantity')::numeric,0,base.unit,base.location,base.pallet_number,'pending',base.ordered_by,base.order_date,base.eta,base.notes,target_job.id is not null,case when target_job.id is not null then concat_ws(' — ',nullif(target_job.job_number,''),target_job.name) end,case when target_job.id is not null then 'Reserved by immutable PO line allocation.' end,target_job.id,p_issuance_id,base.source_purchase_order_line_id,base.source_purchase_order_line_number,base.source_purchase_order_number,coalesce(target_job.id::text,'stock')) returning id into pending_receival_id;
   end if;
   source_line_id:=base.source_purchase_order_line_id;source_line_number:=base.source_purchase_order_line_number;creation_status:='created';return next;
  end loop;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.delete_receiving_import_draft(p_document_id uuid, p_finalize boolean DEFAULT false)
 RETURNS TABLE(storage_paths text[], finalized boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare selected_document public.receiving_documents%rowtype; owned_paths text[];
begin
  perform public.require_app_capability('adjustInventory');
  select * into selected_document from public.receiving_documents where id=p_document_id for update;
  if not found then raise exception 'Receiving Import was not found.'; end if;
  if selected_document.uploaded_by_user_id<>auth.uid() then raise exception 'Only the uploader may delete this Receiving Import.'; end if;

  if p_finalize then
    if selected_document.status<>'deleting' then raise exception 'Receiving Import deletion must remove its stored source before finalization.'; end if;
    delete from public.receiving_documents where id=p_document_id;
    return query select '{}'::text[],true;
    return;
  end if;

  perform 1 from public.pending_receivals p where p.source_receiving_document_id=p_document_id for update;
  if exists(
    select 1 from public.pending_receivals p
    where p.source_receiving_document_id=p_document_id
      and (p.received_at is not null or p.receipt_inventory_item_id is not null or p.receipt_transaction_id is not null)
  ) or exists(
    select 1 from public.inventory_transactions t
    join public.pending_receivals p on p.id=t.pending_receival_id
    where p.source_receiving_document_id=p_document_id
  ) then raise exception 'Cannot delete an import with received inventory history.'; end if;
  if exists(select 1 from public.pending_receivals p where p.source_receiving_document_id=p_document_id and p.status<>'cancelled') then
    raise exception 'Cancel its active Pending Receivals before deleting this import.';
  end if;
  if selected_document.status not in ('review','processing','needs_review','ready_to_confirm','failed','deleting','confirmed') then
    raise exception 'This Receiving Import cannot be deleted in its current state.';
  end if;

  select array_agg(distinct path order by path) into owned_paths from (
    select selected_document.storage_path as path
    union all
    select name from storage.objects where bucket_id='receiving-documents' and name like p_document_id::text||'/%'
  ) paths where nullif(trim(path),'') is not null;

  update public.receiving_document_lines set pending_receival_id=null where receiving_document_id=p_document_id;
  delete from public.pending_receivals where source_receiving_document_id=p_document_id and status='cancelled';
  update public.receiving_documents set status='deleting',processing_stage='Deleting import',processing_error=null,
    confirmed_at=null,confirmed_by_user_id=null,confirmed_by_name=null where id=p_document_id;
  return query select coalesce(owned_paths,'{}'::text[]),false;
end;
$function$

CREATE OR REPLACE FUNCTION public.po_base_undo_pending_receival(p_receival_id uuid, p_actor text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    perform public.require_app_capability('adjustInventory');
  end if;
  perform public.tenops_undo_pending_receival_impl(p_receival_id, p_actor, p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.receive_pending_receival_quantity(p_receival_id uuid, p_received_by text, p_quantity numeric, p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  receival public.pending_receivals%rowtype;
  destination public.inventory_items%rowtype;
  remaining_quantity numeric;
  reservation_label text;
  reservation_enabled boolean;
  transaction_vendor text;
  destination_found boolean := false;
  created_inventory_item boolean := false;
  destination_id bigint;
  new_receipt_transaction_id uuid;
  receipt_note text;
  event_time timestamptz := clock_timestamp();
  prior jsonb;
  receipt_catalog_source text:='standard';
  replay public.pending_receival_receipt_batches%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
   perform public.require_app_capability('receiveInventory');
 end if;
  if p_request_id is null or p_quantity is null or p_quantity<=0 or p_quantity::text in('NaN','Infinity','-Infinity') then raise exception 'A positive receipt quantity and request ID are required.' using errcode='22023'; end if;
  if nullif(trim(p_received_by), '') is null then
    raise exception 'Received by is required.';
  end if;

  select * into receival
  from public.pending_receivals
  where id = p_receival_id
  for update;

  if not found then raise exception 'Pending receival was not found.'; end if;
  select * into replay from public.pending_receival_receipt_batches where request_id=p_request_id;
  if found then
    if replay.pending_receival_id<>p_receival_id or replay.quantity<>p_quantity or replay.reversed_at is not null then raise exception 'Receipt request ID was already used for a different or reversed receipt.'; end if;
    return;
  end if;
  prior:=to_jsonb(receival);
  if receival.source_purchase_order_issuance_id is not null then
    select coalesce(nullif(item->>'catalog_source',''),'standard') into receipt_catalog_source from public.purchase_order_issuances i cross join lateral jsonb_array_elements(i.lines_snapshot)item where i.id=receival.source_purchase_order_issuance_id and item->>'purchase_order_line_id'=receival.source_purchase_order_line_id::text;
  end if;
  if receival.status <> 'pending' then
    raise exception 'Pending receival is no longer receivable.';
  end if;

  remaining_quantity := receival.quantity_expected - coalesce(receival.quantity_received, 0);
  if receival.quantity_expected is null
    or coalesce(receival.quantity_received, 0) < 0
    or coalesce(receival.quantity_received, 0) > receival.quantity_expected then
    raise exception 'Pending receival has invalid expected or received quantities.';
  end if;
  if p_quantity>remaining_quantity then raise exception 'Receipt exceeds remaining expected quantity.' using errcode='22023'; end if;
  remaining_quantity:=p_quantity;

  if receival.production_job_id is not null then
    select coalesce(
      nullif(trim(receival.earmarked_job_name), ''),
      case when nullif(trim(job_number), '') is not null then trim(job_number) || ' — ' || name else name end
    ) into reservation_label
    from public.jobs where id = receival.production_job_id;
  else
    reservation_label := coalesce(
      nullif(trim(receival.temporary_job_label), ''),
      nullif(trim(receival.earmarked_job_name), '')
    );
  end if;

  reservation_enabled := receival.production_job_id is not null
    or nullif(trim(receival.temporary_job_label), '') is not null
    or coalesce(receival.is_earmarked, false);
  transaction_vendor := coalesce(nullif(trim(receival.vendor), ''), 'Unspecified');
  receipt_note := concat_ws(' ', 'Received from pending receival.', nullif(receival.notes, ''));

  if not reservation_enabled then
    select * into destination
    from public.inventory_items inventory
    where lower(trim(coalesce(inventory.vendor, ''))) = lower(trim(coalesce(receival.vendor, '')))
      and lower(trim(coalesce(inventory.color, ''))) = lower(trim(coalesce(receival.material_name, '')))
      and lower(trim(coalesce(inventory.size, ''))) = lower(trim(coalesce(receival.size, '')))
      and lower(trim(coalesce(inventory.category, ''))) = lower(trim(coalesce(receival.category, '')))
      and lower(trim(coalesce(inventory.unit, 'Bags'))) = lower(trim(coalesce(nullif(receival.unit, ''), 'Bags')))
      and lower(trim(coalesce(inventory.location, 'Denton'))) = lower(trim(coalesce(nullif(receival.location, ''), 'Denton')))
      and lower(trim(coalesce(inventory.pallet_number, ''))) = lower(trim(coalesce(receival.pallet_number, '')))
      and coalesce(inventory.earmarked_for_job, false) = false
      and inventory.production_job_id is null
      and nullif(trim(inventory.temporary_job_label), '') is null
    order by inventory.updated_at desc nulls last, inventory.id desc
    limit 1 for update;
    destination_found := found;
  end if;

  if destination_found then
    destination_id := destination.id;
    update public.inventory_items
    set quantity = coalesce(quantity, 0) + remaining_quantity,
        updated_at = event_time,
        last_counted_at = event_time
    where id = destination_id;
  else
    insert into public.inventory_items (
      vendor, color, size, category, quantity, unit, location, pallet_number, notes,
      earmarked_for_job, earmarked_job, earmark_notes, production_job_id, temporary_job_label,
      updated_at, last_counted_at
    ) values (
      nullif(receival.vendor, ''), receival.material_name, nullif(receival.size, ''), nullif(receival.category, ''),
      remaining_quantity, coalesce(nullif(receival.unit, ''), 'Bags'),
      coalesce(nullif(receival.location, ''), 'Denton'), nullif(receival.pallet_number, ''), receival.notes,
      reservation_enabled, reservation_label, nullif(receival.earmark_notes, ''), receival.production_job_id,
      nullif(trim(receival.temporary_job_label), ''), event_time, event_time
    ) returning id into destination_id;
    created_inventory_item := true;
  end if;

  insert into public.inventory_transactions (
    transaction_type, vendor, item_name, size, unit, quantity, location, notes,
    catalog_source, is_earmarked, earmarked_job_name, earmarked_job_id,
    earmark_notes, production_job_id, temporary_job_label, synced_to_inventory_at,
    pending_receival_id, inventory_item_id
  ) values (
    'intake', transaction_vendor, receival.material_name, nullif(receival.size, ''),
    coalesce(nullif(receival.unit, ''), 'Bags'), remaining_quantity,
    coalesce(nullif(receival.location, ''), 'Denton'), receipt_note,
    coalesce(receipt_catalog_source,'standard'), reservation_enabled, reservation_label, null, nullif(receival.earmark_notes, ''),
    receival.production_job_id, nullif(trim(receival.temporary_job_label), ''), event_time,
    receival.id, destination_id
  ) returning id into new_receipt_transaction_id;

  update public.pending_receivals
  set quantity_received = coalesce(receival.quantity_received,0)+p_quantity,
      status = case when coalesce(receival.quantity_received,0)+p_quantity=receival.quantity_expected then 'received' else 'pending' end,
      received_by = trim(p_received_by),
      received_at = event_time,
      receipt_inventory_item_id = destination_id,
      receipt_transaction_id = new_receipt_transaction_id,
      receipt_created_inventory_item = created_inventory_item
  where id = p_receival_id;
  insert into public.pending_receival_receipt_batches(request_id,pending_receival_id,quantity,prior_state,transaction_id,received_by_user_id,received_by_auth_role) values(p_request_id,p_receival_id,p_quantity,prior,new_receipt_transaction_id,case when auth.role()='service_role' then null else auth.uid() end,auth.role());
end;
$function$

CREATE OR REPLACE FUNCTION public.receive_pending_receival_with_reservation(p_receival_id uuid, p_received_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare remaining numeric;
begin
 if coalesce(auth.role(), '') <> 'service_role' then
   perform public.require_app_capability('receiveInventory');
 end if;
 select quantity_expected-coalesce(quantity_received,0) into strict remaining from public.pending_receivals where id=p_receival_id for update;
 perform public.receive_pending_receival_quantity(p_receival_id,p_received_by,remaining,gen_random_uuid());
end $function$

CREATE OR REPLACE FUNCTION public.replace_receiving_import_source(p_document_id uuid, p_storage_path text, p_filename text, p_media_type text, p_size_bytes bigint, p_sha256 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare old_path text;
begin
  perform public.require_app_capability('adjustInventory');
  select storage_path into old_path from public.receiving_documents
    where id=p_document_id and uploaded_by_user_id=auth.uid() and status<>'confirmed' for update;
  if not found then raise exception 'Editable Receiving draft was not found.'; end if;
  delete from public.receiving_document_lines where receiving_document_id=p_document_id;
  update public.receiving_documents set storage_path=p_storage_path,original_filename=p_filename,media_type=p_media_type,size_bytes=p_size_bytes,
    source_sha256=p_sha256,status='processing',processing_stage='Source saved',processing_error=null,extracted_text=null,
    diagnostic_payload='{}'::jsonb,extraction_warnings='{}',vendor_id=null,vendor_name_snapshot=null,suggested_production_job_id=null
  where id=p_document_id;
  return old_path;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_purchasing_catalog_item(p_item jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  item_id uuid := nullif(p_item->>'id','')::uuid;
  selected_vendor uuid := nullif(p_item->>'vendor_id','')::uuid;
  vendor_name text;
  individual_price numeric := round(nullif(p_item->>'price','')::numeric, 2);
  selected_bulk_price numeric := round(nullif(p_item->>'bulk_price','')::numeric, 2);
  selected_bulk_minimum numeric := nullif(p_item->>'bulk_minimum_quantity','')::numeric;
  selected_bulk_uom text := nullif(trim(p_item->>'bulk_minimum_uom'),'');
  selected_truckload_price numeric := round(nullif(p_item->>'truckload_price','')::numeric, 2);
  selected_truckload_minimum numeric := nullif(p_item->>'truckload_minimum_quantity','')::numeric;
  selected_truckload_uom text := nullif(trim(p_item->>'truckload_minimum_uom'),'');
begin
  select name into vendor_name from public.vendors where id=selected_vendor;
  if vendor_name is null then raise exception 'Select a configured Vendor.'; end if;
  if nullif(trim(p_item->>'item_name'),'') is null then raise exception 'Material name is required.'; end if;
  if individual_price is not null and individual_price < 0 then raise exception 'Individual catalog price cannot be negative.'; end if;
  if selected_bulk_price is not null and selected_bulk_price < 0 then raise exception 'Bulk catalog price cannot be negative.'; end if;
  if selected_bulk_minimum is not null and selected_bulk_minimum <= 0 then raise exception 'Bulk minimum quantity must be positive.'; end if;
  if selected_truckload_price is not null and selected_truckload_price < 0 then raise exception 'Truckload catalog price cannot be negative.'; end if;
  if selected_truckload_minimum is not null and selected_truckload_minimum <= 0 then raise exception 'Truckload minimum quantity must be positive.'; end if;
  if (selected_bulk_price is not null or selected_bulk_minimum is not null or selected_bulk_uom is not null)
     and (selected_bulk_minimum is null or selected_bulk_uom is null) then
    raise exception 'Bulk pricing requires a positive minimum quantity and compatible unit.';
  end if;
  if (selected_truckload_price is not null or selected_truckload_minimum is not null or selected_truckload_uom is not null)
     and (selected_truckload_minimum is null or selected_truckload_uom is null) then
    raise exception 'Truckload pricing requires a positive minimum quantity and compatible unit.';
  end if;
  if selected_bulk_minimum is not null
     and selected_truckload_minimum is not null
     and lower(trim(selected_bulk_uom)) = lower(trim(selected_truckload_uom))
     and selected_truckload_minimum <= selected_bulk_minimum then
    raise exception 'Truckload minimum quantity must be greater than the Bulk minimum for the same unit.';
  end if;

  if item_id is null then
    insert into public.vendor_catalog_v2 (
      vendor_id,vendor_name,vendor_sku,category,item_name,size,unit_size,unit_size_uom,packaging,
      price,bulk_price,bulk_minimum_quantity,bulk_minimum_uom,
      truckload_price,truckload_minimum_quantity,truckload_minimum_uom,
      price_unit,quote_required,is_active,lead_time_days,minimum_order_qty,minimum_order_uom,
      notes,product_line,material_type,canonical_vendor,canonical_item_name,canonical_size,
      pricing_status,updated_at
    ) values (
      selected_vendor,vendor_name,nullif(trim(p_item->>'vendor_sku'),''),
      coalesce(nullif(trim(p_item->>'category'),''),'Chip / Aggregate'),
      trim(p_item->>'item_name'),nullif(trim(p_item->>'size'),''),
      nullif(p_item->>'unit_size','')::numeric,nullif(trim(p_item->>'unit_size_uom'),''),
      nullif(trim(p_item->>'packaging'),''),individual_price,
      selected_bulk_price,selected_bulk_minimum,selected_bulk_uom,
      selected_truckload_price,selected_truckload_minimum,selected_truckload_uom,
      nullif(trim(p_item->>'price_unit'),''),individual_price is null,
      coalesce((p_item->>'is_active')::boolean,true),nullif(p_item->>'lead_time_days','')::integer,
      nullif(p_item->>'minimum_order_qty','')::numeric,nullif(trim(p_item->>'minimum_order_uom'),''),
      nullif(trim(p_item->>'notes'),''),nullif(trim(p_item->>'product_line'),''),
      coalesce(nullif(trim(p_item->>'material_type'),''),'chip'),vendor_name,
      trim(p_item->>'item_name'),nullif(trim(p_item->>'size'),''),
      case when individual_price is null then 'quote_required' else 'priced' end,now()
    ) returning id into item_id;
  else
    update public.vendor_catalog_v2 set
      vendor_id=selected_vendor,
      price=individual_price,
      bulk_price=selected_bulk_price,
      bulk_minimum_quantity=selected_bulk_minimum,
      bulk_minimum_uom=selected_bulk_uom,
      truckload_price=selected_truckload_price,
      truckload_minimum_quantity=selected_truckload_minimum,
      truckload_minimum_uom=selected_truckload_uom,
      price_unit=nullif(trim(p_item->>'price_unit'),''),
      quote_required=individual_price is null,
      pricing_status=case when individual_price is null then 'quote_required' else 'priced' end,
      updated_at=now()
    where id=item_id and (vendor_id=selected_vendor or vendor_id is null);
    if not found then raise exception 'Vendor catalog item was not found.'; end if;
  end if;
  return item_id;
exception when unique_violation then
  raise exception 'This Vendor SKU already exists for the selected Vendor.';
end;
$function$

CREATE OR REPLACE FUNCTION public.save_receiving_import_draft(p_document_id uuid, p_status text, p_processing_stage text, p_processing_error text, p_extraction_method text, p_extraction_status text, p_warnings text[], p_extracted_text text, p_diagnostic_payload jsonb, p_vendor_id uuid, p_vendor_name text, p_job_id uuid, p_lines jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare line jsonb; selected_document public.receiving_documents%rowtype;
begin
  perform public.require_app_capability('adjustInventory');
  if p_status not in ('processing','needs_review','ready_to_confirm','failed') then raise exception 'Invalid Receiving draft status.'; end if;
  select * into selected_document from public.receiving_documents where id=p_document_id for update;
  if not found or selected_document.uploaded_by_user_id<>auth.uid() or selected_document.status='confirmed' then
    raise exception 'Editable Receiving draft was not found.';
  end if;
  delete from public.receiving_document_lines where receiving_document_id=p_document_id;
  for line in select value from jsonb_array_elements(coalesce(p_lines,'[]'::jsonb)) loop
    insert into public.receiving_document_lines(
      receiving_document_id,source_order,original_source_text,proposed_catalog_source,proposed_catalog_item_id,proposed_material_name,
      proposed_quantity,proposed_unit,confirmed_catalog_source,confirmed_catalog_item_id,selected_inventory_item_id,
      confirmed_material_name,confirmed_size,confirmed_category,confirmed_quantity,confirmed_unit,confirmed_location,
      production_job_id,resolution_type,match_state,match_basis,included
    ) values (
      p_document_id,(line->>'source_order')::integer,nullif(line->>'source_text',''),nullif(line->>'proposed_catalog_source',''),nullif(line->>'proposed_catalog_item_id','')::uuid,nullif(line->>'proposed_material_name',''),
      nullif(line->>'proposed_quantity','')::numeric,nullif(line->>'proposed_unit',''),nullif(line->>'confirmed_catalog_source',''),nullif(line->>'confirmed_catalog_item_id','')::uuid,nullif(line->>'selected_inventory_item_id','')::bigint,
      nullif(line->>'material_name',''),nullif(line->>'size',''),nullif(line->>'category',''),nullif(line->>'quantity','')::numeric,nullif(line->>'unit',''),nullif(line->>'location',''),
      nullif(line->>'production_job_id','')::uuid,coalesce(nullif(line->>'resolution',''),'unresolved'),coalesce(nullif(line->>'match_state',''),'Unmatched'),nullif(line->>'match_basis',''),coalesce((line->>'included')::boolean,true)
    );
  end loop;
  update public.receiving_documents set status=p_status,processing_stage=p_processing_stage,processing_error=p_processing_error,
    extraction_method=p_extraction_method,extraction_status=p_extraction_status,extraction_warnings=coalesce(p_warnings,'{}'),
    extracted_text=p_extracted_text,diagnostic_payload=coalesce(p_diagnostic_payload,'{}'::jsonb),vendor_id=p_vendor_id,
    vendor_name_snapshot=p_vendor_name,suggested_production_job_id=p_job_id
  where id=p_document_id;
end;
$function$

