CREATE OR REPLACE FUNCTION public.tenops_confirm_receiving_document_import_impl(p_document_id uuid, p_actor text)
 RETURNS TABLE(pending_receival_id uuid, receiving_document_line_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  selected_document public.receiving_documents%rowtype;
  selected_line public.receiving_document_lines%rowtype;
  selected_inventory public.inventory_items%rowtype;
  confirmed_material text;
  created_id uuid;
begin
  perform public.require_app_capability('adjustInventory');
  if nullif(trim(p_actor),'') is null then raise exception 'Reviewer name is required.'; end if;
  select * into selected_document from public.receiving_documents where id=p_document_id for update;
  if not found then raise exception 'Receiving document was not found.'; end if;
  if selected_document.status='confirmed' then
    return query select l.pending_receival_id,l.id from public.receiving_document_lines l
      where l.receiving_document_id=p_document_id and l.included order by l.source_order;
    return;
  end if;
  if selected_document.uploaded_by_user_id<>auth.uid() then raise exception 'Only the uploader may confirm this import.'; end if;
  if not exists(select 1 from public.receiving_document_lines where receiving_document_id=p_document_id and included) then
    raise exception 'Select at least one reviewed material line.';
  end if;

  for selected_line in select * from public.receiving_document_lines where receiving_document_id=p_document_id and included order by source_order for update loop
    if selected_line.pending_receival_id is not null then raise exception 'An import line has already been confirmed.'; end if;
    if selected_line.resolution_type='catalog' and (selected_line.confirmed_catalog_source is null or selected_line.confirmed_catalog_item_id is null) then
      raise exception 'Every catalog line must identify a catalog item.';
    end if;

    confirmed_material := trim(selected_line.confirmed_material_name);
    if selected_line.resolution_type='inventory' then
      if selected_line.selected_inventory_item_id is null then raise exception 'Every Existing Inventory line must identify an Inventory item.'; end if;
      select * into selected_inventory from public.inventory_items
        where id=selected_line.selected_inventory_item_id for share;
      if not found or nullif(trim(selected_inventory.color),'') is null then
        raise exception 'The selected Existing Inventory material is no longer available.';
      end if;
      confirmed_material := trim(selected_inventory.color);
    elsif selected_line.resolution_type='non_catalog' and exists (
      select 1 from public.inventory_items inventory
      where regexp_replace(lower(trim(coalesce(inventory.color,''))),'[[:space:]]+',' ','g')
          = regexp_replace(lower(trim(coalesce(selected_line.confirmed_material_name,''))),'[[:space:]]+',' ','g')
        and regexp_replace(lower(trim(coalesce(inventory.size,''))),'[[:space:]]+',' ','g')
          = regexp_replace(lower(trim(coalesce(selected_line.confirmed_size,''))),'[[:space:]]+',' ','g')
    ) then
      raise exception 'Existing Inventory already contains material "%" with this size. Resolve the line using Existing Inventory before confirming.', selected_line.confirmed_material_name;
    end if;

    insert into public.pending_receivals(
      vendor,material_name,size,category,quantity_expected,quantity_received,unit,location,status,ordered_by,order_date,
      notes,is_earmarked,earmarked_job_name,production_job_id,source_receiving_document_id,source_receiving_document_line_id
    ) values (
      selected_document.vendor_name_snapshot,confirmed_material,selected_line.confirmed_size,selected_line.confirmed_category,
      selected_line.confirmed_quantity,0,selected_line.confirmed_unit,coalesce(nullif(trim(selected_line.confirmed_location),''),'Denton'),'pending',
      trim(p_actor),current_date,'Source: Receiving Document Import',selected_line.production_job_id is not null,
      case when selected_line.production_job_id is not null then coalesce((select nullif(trim(concat_ws(' — ',j.job_number,j.name)),'') from public.jobs j where j.id=selected_line.production_job_id),'Production Job') else null end,
      selected_line.production_job_id,p_document_id,selected_line.id
    ) returning id into created_id;
    update public.receiving_document_lines set pending_receival_id=created_id where id=selected_line.id;
    pending_receival_id:=created_id;
    receiving_document_line_id:=selected_line.id;
    return next;
  end loop;
  update public.receiving_documents set status='confirmed',confirmed_by_user_id=auth.uid(),confirmed_by_name=trim(p_actor),confirmed_at=now()
    where id=p_document_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.tenops_create_pending_receivals_from_po_impl(p_issuance_id uuid, p_lines jsonb, p_actor text)
 RETURNS TABLE(pending_receival_id uuid, source_line_id uuid, source_line_number integer, creation_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  selected_issuance public.purchase_order_issuances%rowtype;
  order_data jsonb;
  snapshot_lines jsonb;
  submitted_line jsonb;
  snapshot_line jsonb;
  selected_line_id uuid;
  selected_line_number integer;
  selected_job_id uuid;
  selected_po_number text;
  selected_job_name text;
  selected_job_number text;
  selected_vendor text;
  selected_material text;
  selected_size text;
  selected_category text;
  selected_unit text;
  selected_location text;
  selected_eta date;
  selected_quantity numeric;
  selected_sku text;
  selected_line_notes text;
  provenance_note text;
  inserted_id uuid;
begin
  if p_issuance_id is null then
    raise exception 'An issuance ID is required.';
  end if;
  if nullif(trim(p_actor), '') is null then
    raise exception 'An actor is required.';
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Select at least one eligible Purchase Order line.';
  end if;

  select issuance.*
  into selected_issuance
  from public.purchase_order_issuances issuance
  where issuance.id = p_issuance_id
  for share;

  if not found then
    raise exception 'The immutable Purchase Order issuance was not found.';
  end if;

  if not exists (
    select 1
    from public.purchase_order_documents document
    where document.issuance_id = selected_issuance.id
      and document.status = 'generated'
      and document.snapshot_hash = selected_issuance.snapshot_hash
      and nullif(trim(document.storage_path), '') is not null
  ) then
    raise exception 'The permanent Purchase Order PDF must be generated before Pending Receivals can be created.';
  end if;

  order_data := selected_issuance.order_snapshot;
  snapshot_lines := selected_issuance.lines_snapshot;
  selected_po_number := nullif(trim(order_data ->> 'po_number'), '');
  selected_job_name := nullif(trim(order_data ->> 'job_name'), '');
  selected_job_number := nullif(trim(order_data ->> 'job_number'), '');
  selected_vendor := nullif(trim(order_data ->> 'vendor_name'), '');
  selected_job_id := nullif(order_data ->> 'production_job_id', '')::uuid;

  if selected_vendor is null then
    raise exception 'The issued Purchase Order does not contain a Vendor name.';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_lines) submitted
    group by submitted ->> 'source_line_id'
    having count(*) > 1
  ) then
    raise exception 'A Purchase Order line was selected more than once.';
  end if;

  for submitted_line in select value from jsonb_array_elements(p_lines)
  loop
    begin
      selected_line_id := nullif(submitted_line ->> 'source_line_id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'A selected Purchase Order line has an invalid source identity.';
    end;
    if selected_line_id is null then
      raise exception 'Every selected line requires its immutable source identity.';
    end if;

    select value
    into snapshot_line
    from jsonb_array_elements(snapshot_lines)
    where value ->> 'purchase_order_line_id' = selected_line_id::text;

    if snapshot_line is null then
      raise exception 'Purchase Order line % is not part of this immutable issuance.', selected_line_id;
    end if;

    selected_line_number := nullif(snapshot_line ->> 'line_number', '')::integer;
    if coalesce(snapshot_line ->> 'line_kind', '') not in ('chip','resin','pigment','filler','other')
      or coalesce((snapshot_line ->> 'quantity')::numeric, 0) <= 0
      or nullif(trim(snapshot_line ->> 'material'), '') is null
      or nullif(trim(snapshot_line ->> 'unit'), '') is null then
      raise exception 'Purchase Order line % is not eligible for Pending Receivals.', coalesce(selected_line_number::text, selected_line_id::text);
    end if;

    selected_material := nullif(trim(submitted_line ->> 'material_name'), '');
    selected_size := nullif(trim(submitted_line ->> 'size'), '');
    selected_category := nullif(trim(submitted_line ->> 'category'), '');
    selected_unit := nullif(trim(submitted_line ->> 'unit'), '');
    selected_location := nullif(trim(submitted_line ->> 'location'), '');
    selected_quantity := nullif(submitted_line ->> 'quantity_expected', '')::numeric;
    selected_eta := nullif(submitted_line ->> 'eta', '')::date;

    if selected_material is null or selected_unit is null or selected_location is null
      or selected_quantity is null or selected_quantity <= 0 then
      raise exception 'Line % requires material, positive quantity, unit, and location.', selected_line_number;
    end if;

    selected_sku := nullif(trim(snapshot_line ->> 'vendor_sku'), '');
    selected_line_notes := nullif(trim(snapshot_line ->> 'notes'), '');
    provenance_note := concat_ws(' | ',
      'Created from PO ' || coalesce(selected_po_number, 'Unnumbered'),
      'Line ' || selected_line_number,
      case when selected_sku is not null then 'SKU ' || selected_sku end
    );
    if selected_line_notes is not null then
      provenance_note := provenance_note || E'\n' || selected_line_notes;
    end if;

    insert into public.pending_receivals (
      vendor,
      material_name,
      size,
      category,
      quantity_expected,
      quantity_received,
      unit,
      location,
      status,
      ordered_by,
      order_date,
      eta,
      notes,
      is_earmarked,
      earmarked_job_name,
      earmark_notes,
      production_job_id,
      temporary_job_label,
      source_purchase_order_issuance_id,
      source_purchase_order_line_id,
      source_purchase_order_line_number,
      source_purchase_order_number
    ) values (
      selected_vendor,
      selected_material,
      selected_size,
      selected_category,
      selected_quantity,
      0,
      selected_unit,
      selected_location,
      'pending',
      trim(p_actor),
      coalesce(nullif(order_data ->> 'po_date', '')::date, selected_issuance.issued_at::date),
      selected_eta,
      provenance_note,
      selected_job_id is not null,
      case when selected_job_id is not null then selected_job_name end,
      case when selected_job_id is not null then concat_ws(' | ',
        case when selected_po_number is not null then 'PO ' || selected_po_number end,
        case when selected_job_number is not null then 'Job ' || selected_job_number end
      ) end,
      selected_job_id,
      null,
      selected_issuance.id,
      selected_line_id,
      selected_line_number,
      selected_po_number
    )
    on conflict (
      source_purchase_order_issuance_id,
      source_purchase_order_line_id
    ) where source_purchase_order_issuance_id is not null
      and source_purchase_order_line_id is not null and source_allocation_key='legacy'
    do nothing
    returning id into inserted_id;

    if inserted_id is null then
      select receival.id
      into inserted_id
      from public.pending_receivals receival
      where receival.source_purchase_order_issuance_id = selected_issuance.id
        and receival.source_purchase_order_line_id = selected_line_id;

      return query select inserted_id, selected_line_id, selected_line_number, 'existing'::text;
    else
      return query select inserted_id, selected_line_id, selected_line_number, 'created'::text;
    end if;
    inserted_id := null;
    snapshot_line := null;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.tenops_receive_pending_receival_impl(p_receival_id uuid, p_received_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  receival public.pending_receivals%rowtype;
  destination public.inventory_items%rowtype;
  remaining_quantity numeric;
  reservation_label text;
  reservation_enabled boolean;
  transaction_vendor text;
  destination_found boolean := false;
  created_inventory_item boolean := false;
  destination_id bigint;
  new_receipt_transaction_id uuid;
  receipt_note text;
  event_time timestamptz := now();
begin
  if nullif(trim(p_received_by), '') is null then
    raise exception 'Received by is required.';
  end if;

  select * into receival
  from public.pending_receivals
  where id = p_receival_id
  for update;

  if not found then raise exception 'Pending receival was not found.'; end if;
  if receival.status not in ('pending', 'partially_received') then
    raise exception 'Pending receival is no longer receivable.';
  end if;

  remaining_quantity := receival.quantity_expected - coalesce(receival.quantity_received, 0);
  if receival.quantity_expected is null
    or coalesce(receival.quantity_received, 0) < 0
    or coalesce(receival.quantity_received, 0) > receival.quantity_expected then
    raise exception 'Pending receival has invalid expected or received quantities.';
  end if;
  if remaining_quantity <= 0 then raise exception 'Pending receival has no remaining quantity.'; end if;

  if receival.production_job_id is not null then
    select coalesce(
      nullif(trim(receival.earmarked_job_name), ''),
      case when nullif(trim(job_number), '') is not null then trim(job_number) || ' — ' || name else name end
    ) into reservation_label
    from public.jobs where id = receival.production_job_id;
  else
    reservation_label := coalesce(
      nullif(trim(receival.temporary_job_label), ''),
      nullif(trim(receival.earmarked_job_name), '')
    );
  end if;

  reservation_enabled := receival.production_job_id is not null
    or nullif(trim(receival.temporary_job_label), '') is not null
    or coalesce(receival.is_earmarked, false);
  transaction_vendor := coalesce(nullif(trim(receival.vendor), ''), 'Unspecified');
  receipt_note := concat_ws(' ', 'Received from pending receival.', nullif(receival.notes, ''));

  if not reservation_enabled then
    select * into destination
    from public.inventory_items inventory
    where lower(trim(coalesce(inventory.vendor, ''))) = lower(trim(coalesce(receival.vendor, '')))
      and lower(trim(coalesce(inventory.color, ''))) = lower(trim(coalesce(receival.material_name, '')))
      and lower(trim(coalesce(inventory.size, ''))) = lower(trim(coalesce(receival.size, '')))
      and lower(trim(coalesce(inventory.category, ''))) = lower(trim(coalesce(receival.category, '')))
      and lower(trim(coalesce(inventory.unit, 'Bags'))) = lower(trim(coalesce(nullif(receival.unit, ''), 'Bags')))
      and lower(trim(coalesce(inventory.location, 'Denton'))) = lower(trim(coalesce(nullif(receival.location, ''), 'Denton')))
      and lower(trim(coalesce(inventory.pallet_number, ''))) = lower(trim(coalesce(receival.pallet_number, '')))
      and coalesce(inventory.earmarked_for_job, false) = false
      and inventory.production_job_id is null
      and nullif(trim(inventory.temporary_job_label), '') is null
    order by inventory.updated_at desc nulls last, inventory.id desc
    limit 1 for update;
    destination_found := found;
  end if;

  if destination_found then
    destination_id := destination.id;
    update public.inventory_items
    set quantity = coalesce(quantity, 0) + remaining_quantity,
        updated_at = event_time,
        last_counted_at = event_time
    where id = destination_id;
  else
    insert into public.inventory_items (
      vendor, color, size, category, quantity, unit, location, pallet_number, notes,
      earmarked_for_job, earmarked_job, earmark_notes, production_job_id, temporary_job_label,
      updated_at, last_counted_at
    ) values (
      nullif(receival.vendor, ''), receival.material_name, nullif(receival.size, ''), nullif(receival.category, ''),
      remaining_quantity, coalesce(nullif(receival.unit, ''), 'Bags'),
      coalesce(nullif(receival.location, ''), 'Denton'), nullif(receival.pallet_number, ''), receival.notes,
      reservation_enabled, reservation_label, nullif(receival.earmark_notes, ''), receival.production_job_id,
      nullif(trim(receival.temporary_job_label), ''), event_time, event_time
    ) returning id into destination_id;
    created_inventory_item := true;
  end if;

  insert into public.inventory_transactions (
    transaction_type, vendor, item_name, size, unit, quantity, location, notes,
    catalog_source, is_earmarked, earmarked_job_name, earmarked_job_id,
    earmark_notes, production_job_id, temporary_job_label, synced_to_inventory_at,
    pending_receival_id, inventory_item_id
  ) values (
    'intake', transaction_vendor, receival.material_name, nullif(receival.size, ''),
    coalesce(nullif(receival.unit, ''), 'Bags'), remaining_quantity,
    coalesce(nullif(receival.location, ''), 'Denton'), receipt_note,
    'standard', reservation_enabled, reservation_label, null, nullif(receival.earmark_notes, ''),
    receival.production_job_id, nullif(trim(receival.temporary_job_label), ''), event_time,
    receival.id, destination_id
  ) returning id into new_receipt_transaction_id;

  update public.pending_receivals
  set quantity_received = quantity_expected,
      status = 'received',
      received_by = trim(p_received_by),
      received_at = event_time,
      receipt_inventory_item_id = destination_id,
      receipt_transaction_id = new_receipt_transaction_id,
      receipt_created_inventory_item = created_inventory_item
  where id = p_receival_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.tenops_undo_pending_receival_impl(p_receival_id uuid, p_actor text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  receival public.pending_receivals%rowtype;
  receipt_tx public.inventory_transactions%rowtype;
  inventory public.inventory_items%rowtype;
  reversal_note text;
  event_time timestamptz := now();
begin
  if nullif(trim(p_actor), '') is null then raise exception 'Your name is required.'; end if;

  select * into receival from public.pending_receivals where id = p_receival_id for update;
  if not found then raise exception 'Pending receival was not found.'; end if;
  if receival.status <> 'received' then raise exception 'Only a received queue item can be undone.'; end if;
  if receival.receipt_transaction_id is null or receival.receipt_inventory_item_id is null
    or receival.receipt_created_inventory_item is null then
    raise exception 'This receipt predates undo tracking and cannot be safely undone automatically.';
  end if;

  select * into receipt_tx
  from public.inventory_transactions
  where id = receival.receipt_transaction_id
  for update;
  if not found or receipt_tx.pending_receival_id is distinct from receival.id
    or receipt_tx.inventory_item_id is distinct from receival.receipt_inventory_item_id
    or receipt_tx.transaction_type <> 'intake'
    or receipt_tx.reversed_at is not null then
    raise exception 'The linked receipt transaction is missing, invalid, or already reversed.';
  end if;

  select * into inventory
  from public.inventory_items
  where id = receival.receipt_inventory_item_id
  for update;
  if not found then raise exception 'The received inventory lot no longer exists.'; end if;
  if inventory.updated_at is distinct from receival.received_at
    or inventory.last_counted_at is distinct from receival.received_at then
    raise exception 'This stock changed after receipt. Reverse its later inventory activity before undoing the receipt.';
  end if;
  if coalesce(inventory.quantity, 0) < receipt_tx.quantity then
    raise exception 'The received quantity is no longer fully available and cannot be undone.';
  end if;

  reversal_note := '[' || trim(p_actor) || '] Undid pending receival receipt.';
  if nullif(trim(p_reason), '') is not null then reversal_note := reversal_note || E'\nReason: ' || trim(p_reason); end if;

  if receival.receipt_created_inventory_item then
    if inventory.quantity <> receipt_tx.quantity then
      raise exception 'The received lot quantity changed after receipt and cannot be undone.';
    end if;
    delete from public.inventory_items where id = inventory.id;
  else
    update public.inventory_items
    set quantity = quantity - receipt_tx.quantity,
        updated_at = event_time,
        last_counted_at = event_time
    where id = inventory.id;
  end if;

  update public.inventory_transactions
  set reversed_at = event_time, reversed_by = trim(p_actor)
  where id = receipt_tx.id;

  insert into public.inventory_transactions (
    transaction_type, vendor, item_name, size, unit, quantity, location, notes,
    catalog_source, is_earmarked, earmarked_job_name, earmarked_job_id,
    earmark_notes, production_job_id, temporary_job_label, synced_to_inventory_at,
    pending_receival_id, inventory_item_id, reversal_of_transaction_id
  ) values (
    'adjustment', receipt_tx.vendor, receipt_tx.item_name, receipt_tx.size, receipt_tx.unit,
    -receipt_tx.quantity, receipt_tx.location, reversal_note, receipt_tx.catalog_source,
    receipt_tx.is_earmarked, receipt_tx.earmarked_job_name, receipt_tx.earmarked_job_id,
    receipt_tx.earmark_notes, receipt_tx.production_job_id, receipt_tx.temporary_job_label,
    event_time, receival.id,
    case when receival.receipt_created_inventory_item then null else inventory.id end,
    receipt_tx.id
  );

  update public.pending_receivals
  set quantity_received = 0,
      status = 'pending',
      received_by = null,
      received_at = null,
      receipt_inventory_item_id = null,
      receipt_transaction_id = null,
      receipt_created_inventory_item = null
  where id = receival.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.undo_pending_receival_receipt(p_receival_id uuid, p_actor text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.pending_receivals%rowtype; batch public.pending_receival_receipt_batches%rowtype;
begin
 if coalesce(auth.role(), '') <> 'service_role' then
   perform public.require_app_capability('adjustInventory');
 end if;
 select * into strict r from public.pending_receivals where id=p_receival_id for update;
 select * into batch from public.pending_receival_receipt_batches where transaction_id=r.receipt_transaction_id and reversed_at is null for update;
 if not found then perform public.po_base_undo_pending_receival(p_receival_id,p_actor,p_reason);return; end if;
 if r.status not in('received','pending') or coalesce(r.quantity_received,0)<=0 then raise exception 'Only a received or partially received record can undo its latest receipt.'; end if;
 update public.pending_receivals set status='received' where id=r.id;
 perform public.po_base_undo_pending_receival(p_receival_id,p_actor,p_reason);
 update public.pending_receivals set quantity_received=(batch.prior_state->>'quantity_received')::numeric,status=batch.prior_state->>'status',received_by=batch.prior_state->>'received_by',received_at=(batch.prior_state->>'received_at')::timestamptz,receipt_inventory_item_id=(batch.prior_state->>'receipt_inventory_item_id')::bigint,receipt_transaction_id=(batch.prior_state->>'receipt_transaction_id')::uuid,receipt_created_inventory_item=(batch.prior_state->>'receipt_created_inventory_item')::boolean where id=r.id;
 update public.pending_receival_receipt_batches set reversed_at=clock_timestamp() where request_id=batch.request_id;
end $function$
